// Navigate to the actual meeting data inside the nested payload
const meetingData = items[0].json.body[0].body;

// Start building aggregated meeting text
let aggregatedText = `Meeting Title: ${meetingData.title || ''}\n\n`;

// Add participants
if (Array.isArray(meetingData.participants) && meetingData.participants.length > 0) {
  aggregatedText += `Participants:\n`;
  meetingData.participants.forEach((p, index) => {
    aggregatedText += `${index + 1}. ${p.name || ''} - ${p.email || ''}\n`;
  });
  aggregatedText += '\n';
}

// Add summary
aggregatedText += `Summary:\n${meetingData.summary || ''}\n\n`;

// Add action items
if (Array.isArray(meetingData.action_items) && meetingData.action_items.length > 0) {
  aggregatedText += `Action Items:\n`;
  meetingData.action_items.forEach((item, index) => {
    aggregatedText += `${index + 1}. ${item.text}\n`;
  });
  aggregatedText += '\n';
}

// Optional: Include transcript if available
if (meetingData.transcript && Array.isArray(meetingData.transcript.speaker_blocks)) {
  aggregatedText += `Transcript:\n`;
  meetingData.transcript.speaker_blocks.forEach(block => {
    aggregatedText += `${block.speaker?.name || 'Unknown'}: ${block.words}\n`;
  });
}

return [
  {
    json: {
      aggregatedMeetingData: aggregatedText
    }
  }
];

